var RockCommerce={cart:!1,cid:0,components:{},config:{},hooksAfter:{},hooksBefore:{},pidcid:{},products:[],taxrate:0,timers:{},addComponent(c){const cid=++this.cid;this.components[cid]=c;c.$el.setAttribute("rc-cid",cid);if(c.$rctype==="rcproduct")this.products.push(c);const pid=c.$rcattr("rc-pid");if(pid)this.pidcid[pid]=cid;this.trigger("addComponent",c)},after(event,handler){if(!this.hooksAfter[event]){this.hooksAfter[event]=[]}
this.hooksAfter[event].push(handler)},before(event,handler){if(!this.hooksBefore[event]){this.hooksBefore[event]=[]}
this.hooksBefore[event].push(handler)},component(name,config){document.addEventListener("alpine:init",()=>{Alpine.data(name,()=>Object.create(Object.getPrototypeOf(config),Object.getOwnPropertyDescriptors(config)))})},debounce(name,func,wait){if(typeof wait==="undefined")wait=10;clearTimeout(this.timers[name]);this.timers[name]=setTimeout(func,wait)},getComponent(el,type){if(type)el=el.closest(`[x-data=${type}]`);if(!el)return!1;const cid=el.closest("[x-data]").getAttribute("rc-cid");if(!cid)console.error("Component is not initialized");return this.components[cid]},getComponentFromPid(pid){const cid=this.pidcid[pid];if(cid)return this.components[cid]},raw(data){return JSON.parse(JSON.stringify(data||this))},trigger(event,data,callback){let hookEvent={return:data,replace:!1,};if(this.hooksBefore[event]){this.hooksBefore[event].forEach((hook)=>hook(hookEvent))}
if(hookEvent.replace)return;if(typeof callback==="function"){hookEvent.return=callback(hookEvent.return)}
if(this.hooksAfter[event]){this.hooksAfter[event].forEach((hook)=>hook(hookEvent))}
return hookEvent.return},};document.addEventListener("alpine:init",()=>{Alpine.magic("rcpid",(el)=>{const c=RockCommerce.getComponent(el);return c.$rcattr("rc-pid")});Alpine.magic("rcattr",(el)=>{const c=RockCommerce.getComponent(el);return(attr)=>c.$root.getAttribute(attr)});Alpine.magic("rctype",(el)=>{const c=RockCommerce.getComponent(el);return c.$el.getAttribute("x-data")})});document.dispatchEvent(new CustomEvent("RockCommerce:init",{detail:RockCommerce,}))